mapper.select:
SELECT t.id, t.source_type, t.project_id, p.project_name, t.account_id, COALESCE(pa.name, t.account_name) AS account_name, t.transaction_date, t.type, t.amount, t.description FROM ( SELECT id, 'ACCOUNT' AS source_type, project_id, payment_account_id AS account_id, NULL AS account_name, transaction_date, type, amount, description, deleted FROM biz_account UNION ALL SELECT id, 'PAYMENT_TRANSACTION' AS source_type, project_id, account_id, NULL AS account_name, transaction_date, type, amount, description, deleted FROM biz_payment_transaction UNION ALL SELECT id, 'BANK_STATEMENT' AS source_type, NULL AS project_id, account_id, NULL AS account_name, transaction_date, type, amount, description, deleted FROM biz_bank_statement UNION ALL SELECT id, 'GENERAL_LEDGER' AS source_type, NULL AS project_id, NULL AS account_id, account_name, transaction_time AS transaction_date, transaction_type AS type, amount, summary AS description, deleted FROM biz_general_ledger ) t LEFT JOIN biz_project p ON p.id = t.project_id AND p.deleted = 0 LEFT JOIN biz_payment_account pa ON pa.id = t.account_id AND pa.deleted = 0 WHERE t.deleted = 0
AND DATE_FORMAT(t.transaction_date, '%Y-%m') = #{month}
AND t.project_id = #{projectId}
AND t.account_id = #{accountId}
ORDER BY t.transaction_date DESC

SELECT p.id AS project_id, p.project_name, p.contract_amount, p.actual_amount, IFNULL(b.budget_amount, 0) AS budget_amount, IFNULL(c.changed_amount, 0) AS changed_amount, IFNULL(pp.paid_amount, 0) AS paid_amount, IFNULL(ca.allocated_amount, 0) AS allocated_amount FROM biz_project p LEFT JOIN ( SELECT project_id, SUM(amount) AS budget_amount FROM biz_budget WHERE deleted = 0 GROUP BY project_id ) b ON b.project_id = p.id LEFT JOIN ( SELECT project_id, SUM(estimated_cost) AS changed_amount FROM biz_change_request WHERE deleted = 0 AND status = 'APPROVED' GROUP BY project_id ) c ON c.project_id = p.id LEFT JOIN ( SELECT project_id, SUM(payment_amount) AS paid_amount FROM biz_progress_payment WHERE deleted = 0 GROUP BY project_id ) pp ON pp.project_id = p.id LEFT JOIN ( SELECT target_id, SUM(allocation_amount) AS allocated_amount FROM biz_cost_allocation WHERE deleted = 0 AND target_type = 'PROJECT' GROUP BY target_id ) ca ON ca.target_id = p.id WHERE p.deleted = 0
AND p.id = #{projectId}
ORDER BY p.create_time DESC

SELECT m.id AS material_id, m.material_code, m.material_name, m.specification, m.unit, m.current_price, COUNT(a.id) AS transaction_count, IFNULL(SUM(a.amount), 0) AS total_amount FROM biz_material m LEFT JOIN biz_account a ON a.material_id = m.id AND a.deleted = 0 WHERE m.deleted = 0
AND m.id = #{materialId}
AND m.category_id = #{categoryId}
GROUP BY m.id, m.material_code, m.material_name, m.specification, m.unit, m.current_price ORDER BY total_amount DESC

SELECT he.dept_id AS dept_id, d.name AS dept_name, COUNT(*) AS review_count, IFNULL(SUM(CASE WHEN r.status = 'APPROVED' THEN 1 ELSE 0 END), 0) AS finalized_count, IFNULL(SUM(CASE WHEN r.status = 'APPROVED' AND r.final_score IS NOT NULL THEN r.final_score ELSE 0 END), 0) AS sum_final_score, IFNULL(SUM(CASE WHEN r.status = 'APPROVED' AND r.final_score >= 90 THEN 1 ELSE 0 END), 0) AS bucket_a, IFNULL(SUM(CASE WHEN r.status = 'APPROVED' AND r.final_score >= 80 AND r.final_score < 90 THEN 1 ELSE 0 END), 0) AS bucket_b, IFNULL(SUM(CASE WHEN r.status = 'APPROVED' AND r.final_score >= 70 AND r.final_score < 80 THEN 1 ELSE 0 END), 0) AS bucket_c, IFNULL(SUM(CASE WHEN r.status = 'APPROVED' AND r.final_score IS NOT NULL AND r.final_score < 70 THEN 1 ELSE 0 END), 0) AS bucket_d FROM hr_performance_review r LEFT JOIN hr_employee he ON he.id = r.employee_id AND he.deleted = 0 LEFT JOIN sys_dept d ON d.id = he.dept_id AND d.deleted = 0 WHERE r.deleted = 0 AND r.period = #{period}
AND he.dept_id = #{deptId}
GROUP BY he.dept_id, d.name ORDER BY he.dept_id

SELECT a.category AS category, COUNT(*) AS `count`, IFNULL(SUM(a.purchase_price), 0) AS total_value FROM admin_asset a WHERE a.deleted = 0
AND a.category = #{category}
GROUP BY a.category ORDER BY a.category

SELECT IFNULL(SUM(CASE WHEN b.status = 'BORROWING' THEN 1 ELSE 0 END), 0) AS borrowing_count, IFNULL(SUM(CASE WHEN b.status = 'BORROWING' AND b.expected_return_date IS NOT NULL AND b.expected_return_date < CURDATE() THEN 1 ELSE 0 END), 0) AS overdue_count FROM admin_asset_borrow b
JOIN admin_asset a ON a.id = b.asset_id AND a.deleted = 0 AND a.category = #{category}
WHERE b.deleted = 0

SELECT COUNT(*) AS instance_count, IFNULL(SUM(CASE WHEN i.status = 'APPROVED' THEN 1 ELSE 0 END), 0) AS approved_count, IFNULL(AVG(CASE WHEN i.status = 'APPROVED' AND i.started_at IS NOT NULL AND i.ended_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, i.started_at, i.ended_at) END), 0) AS avg_duration_seconds, ( SELECT COUNT(*) FROM bpm_task t WHERE t.deleted = 0 AND t.instance_id IN ( SELECT i.id FROM bpm_instance i WHERE i.deleted = 0
) ) AS task_count, ( SELECT COUNT(*) FROM bpm_task t WHERE t.deleted = 0 AND t.status = 'PENDING' AND t.due_at IS NOT NULL AND t.due_at < NOW() AND t.instance_id IN ( SELECT i.id FROM bpm_instance i WHERE i.deleted = 0
) ) AS overdue_task_count FROM bpm_instance i WHERE i.deleted = 0
